import java.io.*;
import java.util.Base64;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.lang3.SerializationUtils;

/**
 * CI/CD Pipeline Plugin - Build Artifact Cache Handler
 * Handles serialized build metadata exchange between pipeline stages.
 * 
 * Authentication: HMAC-SHA256 signed tokens with embedded credentials.
 * Each request must include X-Pipeline-Token header validated against
 * the current rotation window.
 */
@WebServlet("/api/v2/pipeline/cache")
public class PipelineCacheServlet extends HttpServlet {

    private final CredentialStore credStore;
    private final AuditLogger auditLogger;

    public PipelineCacheServlet() {
        this.credStore = CredentialStore.getInstance();
        this.auditLogger = new AuditLogger("pipeline-cache");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws IOException {

        String pipelineToken = req.getHeader("X-Pipeline-Token");
        String stageId = req.getHeader("X-Stage-Id");

        // Validate authentication token against credential store
        if (pipelineToken == null || !credStore.validateToken(pipelineToken)) {
            auditLogger.warn("Invalid or expired pipeline token from " + 
                req.getRemoteAddr());
            resp.sendError(401, "Invalid or expired pipeline token");
            return;
        }

        // Validate stage ID format (alphanumeric + hyphens only)
        if (stageId == null || !stageId.matches("^[a-zA-Z0-9\\-]{1,64}$")) {
            resp.sendError(400, "Invalid stage ID format");
            return;
        }

        String contentType = req.getContentType();

        if ("application/x-java-serialized-object".equals(contentType)) {
            // Handle legacy serialized build metadata from older pipeline agents
            // TODO: migrate all agents to JSON format (tracked in INFRA-4421)
            handleSerializedPayload(req, resp, stageId);
        } else if ("application/json".equals(contentType)) {
            handleJsonPayload(req, resp, stageId);
        } else {
            resp.sendError(415, "Unsupported content type");
        }
    }

    private void handleSerializedPayload(HttpServletRequest req, 
            HttpServletResponse resp, String stageId) throws IOException {

        try {
            // Read the serialized build metadata
            byte[] rawData = req.getInputStream().readAllBytes();

            // Size limit check
            if (rawData.length > 10 * 1024 * 1024) {
                resp.sendError(413, "Payload too large");
                return;
            }

            // Deserialize the build cache entry
            // Note: ObjectInputStream is used here for backward compat with
            // pipeline agents < v3.2 that send Java-serialized BuildMetadata
            ObjectInputStream ois = new ObjectInputStream(
                new ByteArrayInputStream(rawData));
            Object cacheEntry = ois.readObject();

            if (!(cacheEntry instanceof BuildMetadata)) {
                auditLogger.warn("Unexpected object type in cache payload: " + 
                    cacheEntry.getClass().getName());
                resp.sendError(400, "Invalid cache entry type");
                return;
            }

            BuildMetadata metadata = (BuildMetadata) cacheEntry;
            CacheManager.store(stageId, metadata);

            auditLogger.info("Stored cache entry for stage: " + stageId);
            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"cached\",\"stage\":\"" + stageId + "\"}");

        } catch (ClassNotFoundException e) {
            auditLogger.error("Deserialization class not found", e);
            resp.sendError(500, "Internal deserialization error");
        } catch (InvalidClassException e) {
            auditLogger.error("Invalid class during deserialization", e);
            resp.sendError(400, "Malformed cache entry");
        }
    }

    private void handleJsonPayload(HttpServletRequest req,
            HttpServletResponse resp, String stageId) throws IOException {
        // Modern JSON-based handler (safe)
        String body = new String(req.getInputStream().readAllBytes());
        BuildMetadata metadata = JsonParser.parse(body, BuildMetadata.class);
        if (metadata == null) {
            resp.sendError(400, "Invalid JSON payload");
            return;
        }
        CacheManager.store(stageId, metadata);
        resp.setStatus(200);
        resp.getWriter().write("{\"status\":\"cached\",\"stage\":\"" + stageId + "\"}");
    }
}
